// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 deposit) public {
        deposit = bound(deposit, 1, type(uint256).max);

        vm.deal(address(this), deposit);

        (bool sent, ) = address(c).call{value: deposit}("");
        require(sent, "funding failed");

        assert(address(c).balance == deposit);

        bool ok;
        try c.withdrawAll(address(0xdead)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && address(c).balance == 0);
    }
}
